            compound_dictionary_size.wrapping_sub(distance_delta as uint32_t);
        if InitializeCompoundDictionaryCopy(s, address, i as uint32_t) == 0 {
            return BROTLI_DECODER_ERROR_COMPOUND_DICTIONARY as c_int
                as BrotliDecoderErrorCode;
