        let transforms_table = (*dictionary).transforms.as_ptr();
        let mut words: *const BrotliDictionary =
            *words_table.offset(dict_id as isize);
        let mut transforms: *const BrotliTransforms =
            *transforms_table.offset(dict_id as isize);
        let size_bits_by_length = (*words).size_bits_by_length.as_ptr();
        let offsets_by_length = (*words).offsets_by_length.as_ptr();
