        let mut mask: c_int = BitMask(shift) as c_int;
        let mut word_idx: c_int = address_0 & mask;
        let mut transform_idx: c_int = address_0 >> shift;
        (*s).dist_rb_idx += (*s).distance_context;
        offset += word_idx * i;
        if (transform_idx >= (*transforms).num_transforms as c_int
            || *size_bits_by_length.offset(i as isize) as c_int == 0 as c_int)
            && (*dictionary).num_dictionaries as c_int > 1 as c_int
        {
            let mut dict_id2: uint8_t = 0;
            let mut dist_remaining: c_int = address_0
                - ((1 as c_uint) << shift & !(1 as c_uint)) as c_int
                    * (*transforms).num_transforms as c_int;
            dict_id2 = 0 as uint8_t;
            while (dict_id2 as c_int) < (*dictionary).num_dictionaries as c_int {
                let words2: *const BrotliDictionary =
                    *words_table.offset(dict_id2 as isize);
                let size_bits_by_length2 = (*words2).size_bits_by_length.as_ptr();
                if dict_id2 as c_int != dict_id as c_int
                    && *size_bits_by_length2.offset(i as isize) as c_int != 0 as c_int
                {
                    let transforms2: *const BrotliTransforms =
                        *transforms_table.offset(dict_id2 as isize);
                    let shift2: uint64_t =
                        *size_bits_by_length2.offset(i as isize) as uint64_t;
                    let num: c_int =
