            let word: *const uint8_t =
                (*words).data.offset(offset as isize) as *const uint8_t;
            let mut len: c_int = i;
            if transform_idx
                == (*transforms).cutOffTransforms[0 as c_int as usize] as c_int
            {
                memcpy(
                    ringbuffer.offset(pos as isize) as *mut uint8_t as *mut c_void,
                    word as *const c_void,
                    len as size_t,
                );
            } else {
                len = BrotliTransformDictionaryWord(
                    ringbuffer.offset(pos as isize) as *mut uint8_t,
                    word,
                    len,
                    transforms,
                    transform_idx,
                );
                if len == 0 as c_int && distance_code <= 120 as c_int {
                    return BROTLI_DECODER_ERROR_FORMAT_TRANSFORM as c_int
                        as BrotliDecoderErrorCode;
                }
            }
            pos += len;
            (*s).meta_block_remaining_len -= len;
            if pos >= ringbuffer_size {
                (*s).state = BROTLI_STATE_COMMAND_POST_WRITE_1;
                break;
            }
        } else {
            return BROTLI_DECODER_ERROR_FORMAT_TRANSFORM as c_int
                as BrotliDecoderErrorCode;
        }
    } else {
        return BROTLI_DECODER_ERROR_FORMAT_DICTIONARY as c_int
            as BrotliDecoderErrorCode;
    }
} else {
    let src_start: c_int = pos - distance_code & ringbuffer_mask;
    let copy_dst: *mut uint8_t = ringbuffer.offset(pos as isize) as *mut uint8_t;
    let copy_src: *mut uint8_t = ringbuffer.offset(src_start as isize) as *mut uint8_t;
    let dst_end: c_int = pos + i;
    let src_end: c_int = src_start + i;
    (*s).dist_rb[((*s).dist_rb_idx & 3 as c_int) as usize] = distance_code;
    (*s).dist_rb_idx += 1;
    (*s).meta_block_remaining_len -= i;
    memmove16(copy_dst, copy_src);
    if src_end > pos && dst_end > src_start {
        current_block = 3;
        continue;
    }
    if dst_end >= ringbuffer_size || src_end >= ringbuffer_size {
        current_block = 3;
        continue;
    }
    pos += i;
    if i > 16 as c_int {
        if i > 32 as c_int {
            memcpy(
                copy_dst.offset(16 as c_int as isize) as *mut c_void,
                copy_src.offset(16 as c_int as isize) as *const c_void,
                (i - 16 as c_int) as size_t,
            );
        } else {
            memmove16(
                copy_dst.offset(16 as c_int as isize),
                copy_src.offset(16 as c_int as isize),
            );
        }
    }
}
if !((*s).meta_block_remaining_len <= 0 as c_int) {
    current_block = 0;
    continue;
}
(*s).state = BROTLI_STATE_METABLOCK_DONE;
break;

